from typing import List

class Solution:
    def longestCommonPrefix(self, strs: List[str]) -> str:
        first = strs[0]
        for length in range(len(first), -1, -1):
            prefix = first[:length]
            if all(word.startswith(prefix) for word in strs):
                return prefix
        return ""

